  public int compare(  Object obj1,  Object obj2){
    if (obj1 != null) {
      if (!Model.getFacade().isAClassifier(obj1)) {
        throw new ClassCastException(obj1.getClass() + " is not comparable as classifier");
      }
      if (!Model.getFacade().isAClassifier(obj2)) {
        throw new ClassCastException(obj2.getClass() + " is not comparable as classifier");
      }
      String sFilename1=NameGenerator.generateFilename(obj1,iLanguageMajorVersion);
      if (sFilename1 != null) {
        return sFilename1.compareTo(NameGenerator.generateFilename(obj2,iLanguageMajorVersion));
      }
      return (NameGenerator.generateFilename(obj2,iLanguageMajorVersion) != null) ? -1 : 0;
    }
    if (obj2 != null) {
      return -1;
    }
    return 0;
  }
}
